export default class CheckoutStepViewed {
    constructor(details) {
      this.details = details || {};
    }
  
    toSegment() {
      return {
        event: 'Checkout Step Viewed',
        properties: {
          checkout_id: this.details.checkout_id,
          step: this.details.step,
          shipping_method: this.details.shipping_method,
          payment_method: this.details.payment_method
        }
      };
    }
  } 